'use client'

import { useEffect, useMemo, useState } from 'react'
import { motion, AnimatePresence } from 'framer-motion'
import { Bell, ChevronRight, CircleHelp, Coins, Copy, Download, Fuel, History, LayoutDashboard, MoreHorizontal, Plus, Send, Settings, ShieldCheck, Wallet, X, Zap } from 'lucide-react'

const ease = [0.16, 1, 0.3, 1] as const
const navItems = [
  { label: 'Dashboard', icon: LayoutDashboard },
  { label: 'Bots', icon: Zap },
  { label: 'Wallet', icon: Wallet },
  { label: 'Earn', icon: Coins },
  { label: 'Account', icon: Settings },
]

function PulseMark({ size = 34 }: { size?: number }) {
  return <svg aria-label="TradePulse mark" role="img" width={size} height={size} viewBox="0 0 40 40" fill="none"><path d="M3 21h7l3-9 6 18 5-14 3 5h10" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" /><circle cx="37" cy="21" r="1.7" fill="#34D399" /></svg>
}

function GradientPanel({ children, className = '' }: { children: React.ReactNode; className?: string }) { return <div className={`gradient-panel ${className}`}>{children}</div> }

function BootScreen({ onComplete }: { onComplete: () => void }) {
  const [step, setStep] = useState(0)
  const steps = ['verifying session…', 'syncing ledger…', 'loading desk…']
  useEffect(() => { const interval = window.setInterval(() => setStep((current) => Math.min(current + 1, 2)), 650); const done = window.setTimeout(onComplete, 2400); return () => { window.clearInterval(interval); window.clearTimeout(done) } }, [onComplete])
  return <motion.div className="boot-screen" exit={{ opacity: 0 }} transition={{ duration: .65, ease }}><div className="boot-mark"><PulseMark size={76} /></div><div className="boot-line" /><div className="boot-copy"><strong>TRADE<span>PULSE</span></strong><div className="boot-status"><span className="status-dot" />{steps[step]}</div></div></motion.div>
}

function Sidebar({ active, setActive }: { active: string; setActive: (value: string) => void }) { return <aside className="sidebar"><div className="brand"><PulseMark /><span>TRADE<span>PULSE</span></span></div><div className="desk-label">WORKSPACE</div><nav className="side-nav">{navItems.map(({ label, icon: Icon }) => <button key={label} className={`nav-item ${active === label ? 'active' : ''}`} onClick={() => setActive(label)}><Icon size={18} /><span>{label}</span></button>)}<button className={`nav-item ${active === 'Live Desk' ? 'active' : ''}`} onClick={() => setActive('Live Desk')}><Zap size={18} /><span>Live Desk</span></button><button className={`nav-item ${active === 'Admin' ? 'active' : ''}`} onClick={() => setActive('Admin')}><ShieldCheck size={18} /><span>Control room</span></button></nav><div className="sidebar-bottom"><button className="nav-item"><CircleHelp size={18} /><span>Help center</span></button><div className="profile"><div className="avatar">JD</div><div><strong>Jordan Davis</strong><small>Pro account</small></div><MoreHorizontal size={17} /></div></div></aside> }
function BottomNav({ active, setActive }: { active: string; setActive: (value: string) => void }) { return <nav className="bottom-nav">{navItems.map(({ label, icon: Icon }) => <button key={label} className={`bottom-item ${active === label ? 'active' : ''}`} onClick={() => setActive(label)}><span className="bottom-icon">{active === label && <i /> }<Icon size={19} /></span>{active === label && <span>{label}</span>}</button>)}</nav> }

function Header({ setActive }: { setActive: (view: string) => void }) { return <header className="topbar"><div className="mobile-brand"><PulseMark size={27} /><span>TRADE<span>PULSE</span></span></div><div className="page-heading"><span className="eyebrow">WORKSPACE / OVERVIEW</span><h1>Dashboard</h1></div><div className="welcome"><span className="eyebrow">GOOD MORNING</span><strong>Jordan</strong></div><div className="top-actions"><div className="live-indicator"><i />LIVE</div><button className="icon-button admin-shortcut" aria-label="Open control room" onClick={() => setActive('Admin')}><ShieldCheck size={18} /></button><button className="icon-button notification" aria-label="3 notifications"><Bell size={18} /><b>3</b></button><div className="top-avatar" aria-label="Jordan Davis avatar">JD</div></div></header> }

function CountUp({ value, decimals = 2, prefix = '$' }: { value: number; decimals?: number; prefix?: string }) { const [current, setCurrent] = useState(0); useEffect(() => { let frame = 0; const start = performance.now(); const tick = (now: number) => { const progress = Math.min((now - start) / 900, 1); setCurrent(value * (1 - Math.pow(1 - progress, 3))); if (progress < 1) frame = requestAnimationFrame(tick) }; frame = requestAnimationFrame(tick); return () => cancelAnimationFrame(frame) }, [value]); return <>{prefix}{current.toLocaleString('en-US', { minimumFractionDigits: decimals, maximumFractionDigits: decimals })}</> }

function BalanceHero() { return <GradientPanel className="balance-hero reveal-card"><div className="panel-heading"><div><span className="eyebrow">TOTAL EQUITY</span><button className="visibility" aria-label="Hide balance">•••</button></div><span className="positive-chip">+12.84%</span></div><div className="balance"><CountUp value={24892.42} /></div><div className="balance-change">+$2,836.12 <span>this month</span></div><div className="balance-breakdown"><div><span>AVAILABLE</span><strong><CountUp value={8420.35} /></strong></div><div><span>INVESTED</span><strong><CountUp value={16472.07} /></strong></div></div><div className="hero-chart"><svg viewBox="0 0 600 100" preserveAspectRatio="none" aria-label="Equity growth chart"><path d="M0 81 C35 78 42 72 62 75 S95 53 115 64 S153 56 176 61 S208 45 235 51 S263 65 285 45 S320 48 345 35 S373 43 398 30 S427 42 452 24 S480 33 505 19 S550 27 600 7" fill="none" stroke="#34D399" strokeWidth="2" /></svg></div></GradientPanel> }

const bots = [{ name: 'Memecoin', allocation: '$4,250.00', equity: '$5,084.20', percent: 78, gain: '+19.63%', state: 'running', compound: '100%' }, { name: 'Synthetic', allocation: '$8,600.00', equity: '$8,112.44', percent: 46, gain: '-5.67%', state: 'paused', compound: '50%' }]
function BotRing({ percent, state }: { percent: number; state: string }) { return <div className={`bot-ring ${state}`} style={{ '--progress': `${percent * 3.6}deg` } as React.CSSProperties}><div className="ring-core"><i /></div></div> }
function MiniSparkline({ negative = false }: { negative?: boolean }) { return <svg className={`mini-sparkline ${negative ? 'negative' : ''}`} viewBox="0 0 120 38" preserveAspectRatio="none" aria-label="Bot equity sparkline"><path d={negative ? 'M2 10 C20 9 24 18 38 14 S57 22 72 17 S91 25 118 30' : 'M2 30 C17 27 21 19 35 24 S54 9 70 18 S87 8 101 12 S112 6 118 3'} fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" /></svg> }
function BotCard({ bot }: { bot: typeof bots[number] }) { return <GradientPanel className="bot-card reveal-card"><div className="bot-card-top"><BotRing percent={bot.percent} state={bot.state} /><div className="bot-copy"><div className="bot-title"><strong>{bot.name}</strong><span className={`status-chip ${bot.state}`}><i />{bot.state}</span></div><span className="bot-allocation">Allocation {bot.allocation}</span><div className="bot-equity"><strong>{bot.equity}</strong><span className={bot.state === 'paused' ? 'down' : 'up'}>{bot.gain}</span></div></div></div><div className="bot-card-bottom"><MiniSparkline negative={bot.state === 'paused'} /><span className="compound-chip">COMPOUND {bot.compound}</span></div></GradientPanel> }

function StatChips() { return <div className="stat-chips reveal-card">{[['RUNNING BOTS', '01'], ['PAUSED', '01'], ['ALERTS', '03'], ['TIER', 'PRO'], ['SLOTS', '02 / 05']].map(([label, value]) => <div className="stat-chip" key={label}><span>{label}</span><strong>{value}</strong></div>)}</div> }
function PriceStrip() { const prices = [['BTC/USD', '$67,842.10', '+2.41%', true], ['ETH/USD', '$3,842.66', '+1.08%', true], ['SOL/USD', '$182.44', '-0.74%', false], ['PEPE/USD', '$0.0000124', '+8.92%', true]]; return <div className="price-strip reveal-card">{prices.map(([name, price, change, up]) => <div className="ticker" key={name}><span>{name}</span><strong>{price}</strong><small className={up ? 'up' : 'down'}>{up ? '↗' : '↘'} {change}</small></div>)}</div> }
function Activity() { const items = [['Memecoin bot', 'Equity rebalance', '+$84.20', '2m', 'complete'], ['Synthetic bot', 'Risk threshold reached', '-$42.80', '18m', 'review'], ['Deposit received', 'USDC · Wallet', '+$1,250.00', '1h', 'complete']]; return <GradientPanel className="activity-card reveal-card"><div className="section-heading"><div><span className="eyebrow">RECENT ACTIVITY</span><h2>Ledger activity</h2></div><button className="view-all">View all <ChevronRight size={14} /></button></div><div className="activity-list">{items.map(([title, sub, amount, time, status]) => <div className="activity-row" key={title}><div className="activity-info"><strong>{title}</strong><small>{sub}</small></div><span className={`activity-status ${status}`}>{status}</span><div className="activity-amount"><strong className={amount.startsWith('+') ? 'up' : 'down'}>{amount}</strong><small>{time}</small></div></div>)}</div></GradientPanel> }
function DemoBanner() { return <GradientPanel className="demo-banner reveal-card"><div className="demo-mark"><PulseMark size={28} /></div><div><span className="eyebrow">PRACTICE MODE</span><h2>Try a $50 virtual memecoin demo</h2><p>Explore the desk with zero risk. Your balance stays untouched.</p></div><button aria-label="Try demo"><ChevronRight size={17} /></button></GradientPanel> }
function EmptyBots() { return <GradientPanel className="empty-bots"><svg viewBox="0 0 120 38" aria-label="Flatlined pulse"><path d="M2 20h28l8-9 9 18 8-9h63" fill="none" stroke="currentColor" strokeWidth="2" /></svg><p>No bots are running yet.</p><button>Launch your first bot <ChevronRight size={14} /></button></GradientPanel> }

const walletActions = [{ label: 'Deposit', icon: Download }, { label: 'Withdraw', icon: Send }, { label: 'History', icon: History }, { label: 'Activity', icon: Zap }]
function WalletCard({ label, value, detail, accent = '' }: { label: string; value: string; detail?: string; accent?: string }) { return <GradientPanel className="wallet-stat"><span className="eyebrow">{label}</span><strong className={accent}>{value}</strong>{detail && <small>{detail}</small>}</GradientPanel> }
function StepRail({ current }: { current: number }) { return <div className="step-rail">{['ASSET', 'NETWORK', 'CONFIRM'].map((step, index) => <div className={index < current ? 'done' : index === current ? 'current' : ''} key={step}><b>0{index + 1}</b><span>{index < current ? '✓' : step}</span>{index < 2 && <i />}</div>)}</div> }
function WalletOverview({ setView }: { setView: (view: string) => void }) { return <div className="wallet-grid"><div className="wallet-stat-grid"><WalletCard label="AVAILABLE" value="$8,420.35" detail="Ready to deploy" accent="mint" /><WalletCard label="LOCKED" value="$1,280.00" detail="Until 24 Sep" /><WalletCard label="TOTAL EQUITY" value="$24,892.42" detail="+12.84% this month" accent="mint" /><WalletCard label="HIGH-WATER MARK" value="$26,104.18" detail="Set 12 Aug" /></div><GradientPanel className="gas-card"><div className="section-heading"><div><span className="eyebrow">NETWORK GAS TANK</span><h2>Keep actions moving</h2></div><Fuel size={18} /></div><div className="gas-meter"><div><strong>72%</strong><small>~$14.40 remaining</small></div><div className="gas-track"><i /></div></div><label className="toggle-row"><span>Auto-fill when low<small>Uses available USDC</small></span><input type="checkbox" defaultChecked /><i /></label></GradientPanel><div className="wallet-actions">{walletActions.map(({ label, icon: Icon }) => <button key={label} onClick={() => setView(label === 'History' ? 'Ledger' : label)}><span><Icon /></span><strong>{label}</strong><ChevronRight /></button>)}</div><GradientPanel className="wallet-promo"><ShieldCheck /><div><span className="eyebrow">CUSTODY CONTROL</span><h2>Your funds stay yours.</h2><p>Every movement is recorded, verified, and visible in your ledger.</p></div></GradientPanel></div> }
function DepositFlow() { const [step, setStep] = useState(0); const [copied, setCopied] = useState(false); return <div className="wallet-flow"><StepRail current={step} /><GradientPanel className="flow-card"><div className="flow-title"><div><span className="eyebrow">DEPOSIT · USDC</span><h2>{step === 0 ? 'Choose an asset' : step === 1 ? 'Choose a network' : 'Send USDC to TradePulse'}</h2></div><span className="secure-chip"><ShieldCheck /> SECURE</span></div>{step === 0 && <div className="choice-grid">{['USDT', 'USDC'].map((asset, i) => <button className={i === 1 ? 'selected' : ''} key={asset} onClick={() => setStep(1)}><span className="coin-mark">{asset[0]}</span><strong>{asset}</strong><small>{i === 1 ? 'USD Coin' : 'Tether USD'}</small><ChevronRight /></button>)}</div>}{step === 1 && <div className="choice-grid">{[['Base', 'Low fees · ~2 min'], ['Ethereum', 'Higher fees · ~5 min'], ['Solana', 'Fast · ~1 min']].map(([network, note]) => <button key={network} onClick={() => setStep(2)}><span className="network-mark" /><strong>{network}</strong><small>{note}</small><ChevronRight /></button>)}</div>}{step === 2 && <><div className="qr-placeholder"><div className="qr-grid" /><small>SCAN TO DEPOSIT USDC ON BASE</small></div><div className="copy-field"><code>0x71F4...9aC28D</code><button onClick={() => { setCopied(true); window.setTimeout(() => setCopied(false), 1200) }}>{copied ? '✓' : <Copy />}</button></div><div className="warning-block"><strong>Send USDC on Base only</strong><span>Sending another asset or network may permanently lose funds.</span></div><label className="amount-field"><span>EXPECTED AMOUNT</span><input placeholder="0.00 USDC" inputMode="decimal" /></label><button className="primary-action" onClick={() => setStep(0)}>I made this deposit <ChevronRight /></button></>}</GradientPanel><GradientPanel className="blocking-banner"><X /><div><strong>Deposits temporarily unavailable</strong><span>We’re syncing the Base network. Try again shortly.</span></div><button>Check status</button></GradientPanel><DepositTimeline /></div> }
function DepositTimeline() { return <div className="timeline"><span className="eyebrow">DEPOSIT TIMELINE</span>{['Detected', 'Verified', 'Credited'].map((label, i) => <div className="timeline-row" key={label}><i className={i === 0 ? 'active' : ''}>{i === 0 ? '✓' : i + 1}</i><div><strong>{label}</strong><small>{i === 0 ? 'Waiting for an incoming transaction' : 'Pending detection'}</small></div><span className="status-chip review">pending</span></div>)}</div> }
function Ledger({ setView }: { setView: (view: string) => void }) { const rows = [['USDC deposit', '+$1,250.00', 'verified', 'Today · 09:12'], ['Bot allocation', '-$4,250.00', 'complete', 'Yesterday · 18:42'], ['Withdrawal', '-$800.00', 'pending', '18 Sep · 13:08'], ['Gas refill', '-$12.40', 'complete', '17 Sep · 10:20']]; return <div className="ledger-screen"><div className="ledger-header"><div><span className="eyebrow">WALLET / HISTORY</span><h2>Ledger history</h2></div><button className="view-all" onClick={() => setView('Wallet')}>Overview <ChevronRight /></button></div><div className="filter-chips"><button className="active">All</button><button>Deposits</button><button>Withdrawals</button><button>Bot activity</button></div><GradientPanel className="ledger-card">{rows.map(([title, amount, status, date]) => <div className="ledger-row" key={title}><div><strong>{title}</strong><small>{date} · Base</small></div><span className={`activity-status ${status}`}>{status}</span><code className={amount.startsWith('+') ? 'mint' : ''}>{amount}</code></div>)}</GradientPanel><div className="minimum-warning"><span>!</span><div><strong>Below-minimum deposit</strong><p>Received <code>12.00 USDC</code> · minimum <code>25.00 USDC</code> · remaining <code>13.00 USDC</code></p><small>Send the remaining amount to the same address to credit this deposit.</small></div></div></div> }
function WalletScreen() { const [view, setView] = useState('Wallet'); return view === 'Wallet' ? <WalletOverview setView={setView} /> : view === 'Ledger' ? <Ledger setView={setView} /> : <DepositFlow /> }

type BotView = 'fleet' | 'create-product' | 'create-amount' | 'detail' | 'demo'

function BotProductCard({ name, description, icon, selected, onClick }: { name: string; description: string; icon: string; selected?: boolean; onClick: () => void }) { return <button className={`product-card ${selected ? 'selected' : ''}`} onClick={onClick}><span className="product-icon">{icon}</span><span><strong>{name}</strong><small>{description}</small></span><ChevronRight /></button> }
function BotOverviewCard({ bot, onDetail }: { bot: typeof bots[number]; onDetail: () => void }) { return <GradientPanel className="fleet-bot-card reveal-card"><div className="fleet-bot-head"><BotRing percent={bot.percent} state={bot.state} /><div><div className="bot-title"><strong>{bot.name}</strong><span className={`status-chip ${bot.state}`}><i />{bot.state}</span></div><span className="eyebrow">ALLOCATION</span><strong className="fleet-amount">{bot.allocation}</strong></div></div><div className="fleet-metrics"><div><span>EQUITY</span><strong>{bot.equity}</strong></div><div><span>RETURN</span><strong className={bot.state === 'paused' ? 'down' : 'up'}>{bot.gain}</strong></div><MiniSparkline negative={bot.state === 'paused'} /></div><div className="fleet-bot-actions"><span className="compound-chip">COMPOUND {bot.compound}</span><button className="small-action" onClick={onDetail}>Open detail <ChevronRight /></button></div></GradientPanel> }
function BotCreate({ setView }: { setView: (view: BotView) => void }) { const [product, setProduct] = useState(''); const [amount, setAmount] = useState(''); const [confirm, setConfirm] = useState(false); const [activeModal, setActiveModal] = useState(false); if (!product) return <div className="bot-flow"><div className="flow-kicker"><span className="eyebrow">NEW AUTOMATION</span><h2>Choose a product</h2><p>One strategy per slot. Pick the desk that fits your risk.</p></div><div className="product-grid"><BotProductCard name="Memecoin" description="High volatility · 100% crypto" icon="M" onClick={() => setProduct('Memecoin')} /><BotProductCard name="Synthetic Indices" description="Diversified · market-neutral" icon="S" onClick={() => setProduct('Synthetic Indices')} /></div><button className="text-action" onClick={() => setActiveModal(true)}>Already have an active bot? <ChevronRight /></button>{activeModal && <div className="modal-backdrop"><GradientPanel className="confirm-modal"><span className="eyebrow">SLOT LIMIT</span><h2>Keep your fleet focused.</h2><p>You already have an active bot. Deploy it from Fleet instead of opening a second slot.</p><button className="primary-action" onClick={() => { setActiveModal(false); setView('fleet') }}>Go to Fleet <ChevronRight /></button><button className="ghost-action" onClick={() => setActiveModal(false)}>Not now</button></GradientPanel></div>}</div>;
 return <div className="bot-flow"><button className="back-action" onClick={() => setProduct('')}>← Choose another product</button><div className="flow-kicker"><span className="eyebrow">{product.toUpperCase()} · ALLOCATION</span><h2>How much should we deploy?</h2></div><div className="amount-input"><span>$</span><input value={amount} onChange={(event) => setAmount(event.target.value.replace(/[^0-9.]/g, ''))} placeholder="0.00" inputMode="decimal" aria-label="Allocation amount" /></div><div className="quick-amounts">{['250','500','1,000','2,500'].map((value) => <button key={value} onClick={() => setAmount(value)}>${value}</button>)}</div><div className="available-line"><span>AVAILABLE TO DEPLOY</span><strong>$8,420.35</strong></div><p className="minimum-hint">Minimum allocation is $250.00. You can change compounding after deployment.</p><button className="primary-action" disabled={!amount || Number(amount) < 250} onClick={() => setConfirm(true)}>Review allocation <ChevronRight /></button>{confirm && <div className="modal-backdrop"><GradientPanel className="confirm-modal"><span className="eyebrow">FINAL REVIEW</span><h2>Confirm deployment</h2><div className="fact-block"><span>PRODUCT <b>{product}</b></span><span>ALLOCATION <b>${Number(amount).toLocaleString('en-US',{minimumFractionDigits:2})}</b></span><span>AVAILABLE AFTER <b>${(8420.35-Number(amount)).toLocaleString('en-US',{minimumFractionDigits:2})}</b></span><span>COMPOUNDING <b>50%</b></span></div><button className="primary-action" onClick={() => { setConfirm(false); setView('detail') }}>Deploy bot <Zap /></button><button className="ghost-action" onClick={() => setConfirm(false)}>Go back</button></GradientPanel></div>}</div> }
function BotDetail({ setView }: { setView: (view: BotView) => void }) { const [paused, setPaused] = useState(false); const [compound, setCompound] = useState('50%'); const [close, setClose] = useState(false); const [checked, setChecked] = useState(false); return <div className="bot-detail"><button className="back-action" onClick={() => setView('fleet')}>← Fleet overview</button><GradientPanel className="detail-hero"><div className="detail-ring"><BotRing percent={78} state={paused ? 'paused' : 'running'} /></div><div><span className="eyebrow">MEMECOIN BOT</span><h2>Memecoin</h2><span className={`status-chip ${paused ? 'paused' : 'running'}`}><i />{paused ? 'paused' : 'running'}</span></div></GradientPanel><div className="detail-stats">{[['ALLOCATION','$4,250.00'],['EQUITY','$5,084.20'],['HIGH-WATER MARK','$5,190.10']].map(([label,value]) => <GradientPanel key={label}><span>{label}</span><strong>{value}</strong></GradientPanel>)}</div><GradientPanel className="equity-placeholder"><div className="section-heading"><div><span className="eyebrow">EQUITY CURVE</span><h2>Performance</h2></div><span className="up">+19.63%</span></div><MiniSparkline /><div className="chart-axis"><span>01 SEP</span><span>20 SEP</span></div></GradientPanel><GradientPanel className="compound-panel"><span className="eyebrow">COMPOUNDING</span><div className="segment-control">{['0%','50%','100%'].map(value => <button className={compound === value ? 'active' : ''} key={value} onClick={() => setCompound(value)}>{value}</button>)}</div></GradientPanel><div className="detail-actions"><button className="primary-action" onClick={() => setPaused(!paused)}>{paused ? 'Resume bot' : 'Pause bot'} <Zap /></button><button className="danger-action" onClick={() => setClose(true)}>Close bot <X /></button></div>{close && <div className="modal-backdrop"><GradientPanel className="confirm-modal danger-modal"><span className="eyebrow">PERMANENT ACTION</span><h2>Close Memecoin bot?</h2><p>Your bot will stop trading and return <strong>$5,084.20</strong> to available balance. This cannot be undone.</p><label className="check-confirm"><input type="checkbox" checked={checked} onChange={(event) => setChecked(event.target.checked)} /> I understand closing locks in the current equity.</label><button className="danger-action" disabled={!checked} onClick={() => { setClose(false); setView('fleet') }}>Close bot permanently</button><button className="ghost-action" onClick={() => setClose(false)}>Keep bot</button></GradientPanel></div>}</div> }
function DemoScreen() { return <div className="demo-screen"><GradientPanel className="demo-terms"><span className="eyebrow">PRACTICE MODE · DEMO</span><h2>Trade without the pressure.</h2><p>This demo uses <strong>$50.00 virtual funds</strong>. They are not real money, cannot be withdrawn, and never touch your wallet.</p><div className="virtual-label">VIRTUAL / NON-WITHDRAWABLE</div><button className="primary-action">Activate memecoin demo <ChevronRight /></button></GradientPanel><GradientPanel className="demo-activation"><div><span className="eyebrow">DEMO ACTIVE</span><h2>$50.00 virtual memecoin</h2><p>Expires in <strong className="mono">23:59:42</strong></p></div><div className="demo-countdown mono">23:59:42</div></GradientPanel></div> }
function BotsScreen() { const [view, setView] = useState<BotView>('fleet'); if (view === 'create-product' || view === 'create-amount') return <BotCreate setView={setView} />; if (view === 'detail') return <BotDetail setView={setView} />; if (view === 'demo') return <DemoScreen />; return <div className="bots-screen"><GradientPanel className="fleet-hero"><div><span className="eyebrow">BOT FLEET</span><h2>Automation at a glance</h2><p>2 active strategies · $12,850 deployed</p></div><strong>$13,196.64</strong></GradientPanel><div className="fleet-heading"><div><span className="eyebrow">YOUR STRATEGIES</span><h2>My bots <small>02 / 05</small></h2></div><button className="primary-action" onClick={() => setView('create-product')}><Plus /> Deploy bot</button></div><div className="fleet-bot-grid">{bots.map(bot => <BotOverviewCard key={bot.name} bot={bot} onDetail={() => setView('detail')} />)}</div><button className="demo-link" onClick={() => setView('demo')}>Explore the $50 virtual demo <ChevronRight /></button></div> }

function Dashboard() { return <div className="dashboard-grid"><BalanceHero /><StatChips /><section className="bots-section reveal-card"><div className="section-heading"><div><span className="eyebrow">AUTOMATION</span><h2>My Bots <small>02</small></h2></div><button className="view-all">Manage <ChevronRight size={14} /></button></div><div className="bot-grid">{bots.map((bot) => <BotCard key={bot.name} bot={bot} />)}</div></section><PriceStrip /><Activity /><DemoBanner /><div className="sync-time">LAST SYNCED 09:42:18 UTC · ALL SYSTEMS NOMINAL</div></div> }

function InfoTip({ children }: { children: React.ReactNode }) { const [open, setOpen] = useState(false); return <span className="info-tip"><button aria-label="More information" onClick={() => setOpen(!open)}>?</button>{open && <span>{children}</span>}</span> }
function EarnScreen() { const [copied, setCopied] = useState(false); const [tier, setTier] = useState(false); if (tier) return <><button className="back-action" onClick={() => setTier(false)}>← Referral overview</button><TierScreen /></>; return <div className="account-screen"><div className="screen-title"><div><span className="eyebrow">EARN / REFERRALS</span><h2>Make your desk work harder.</h2></div><button className="share-action" onClick={() => navigator.share?.({ title: 'TradePulse', text: 'Join my TradePulse desk' })}>Share</button></div><GradientPanel className="invite-card"><div><span className="eyebrow">YOUR INVITE LINK</span><code>tradepulse.app/r/jordan-davis</code></div><button onClick={() => { navigator.clipboard?.writeText('tradepulse.app/r/jordan-davis'); setCopied(true); window.setTimeout(() => setCopied(false), 1200) }}>{copied ? 'Copied' : 'Copy link'}</button></GradientPanel><div className="earn-grid"><GradientPanel><span className="eyebrow">ACCRUED EARNINGS</span><strong className="big-number">$286.40</strong><small>+ $42.80 this month</small></GradientPanel><GradientPanel><span className="eyebrow">ACTIVE REFERRALS</span><strong className="big-number">12</strong><small>3 qualified this month</small></GradientPanel></div><GradientPanel className="levels-card"><div className="section-heading"><div><span className="eyebrow">REFERRAL LEVELS</span><h2>Share the upside</h2></div><InfoTip>Level 1 earns 5% of eligible fees. Level 2 earns 2%.</InfoTip></div>{[['01','Direct referrals','5.0%','8'],['02','Second degree','2.0%','4'],['03','Community bonus','1.0%','0']].map(row => <div className="level-row" key={row[0]}><b>{row[0]}</b><span>{row[1]}<small>{row[3]} people</small></span><strong>{row[2]}</strong></div>)}</GradientPanel><GradientPanel className="leaderboard"><div className="section-heading"><div><span className="eyebrow">LEADERBOARD</span><h2>Top desks</h2></div><button className="view-all" onClick={() => setTier(!tier)}>{tier ? 'Hide tier' : 'View tier'} <ChevronRight /></button></div>{[['01','Maya Chen','$1,284.20'],['02','Alex Rivera','$982.40'],['03','Jordan Davis','$286.40'],['04','Noah Kim','$214.10'],['05','Sofia Patel','$180.00']].map(row => <div className="leader-row" key={row[0]}><b className={Number(row[0]) < 4 ? 'medal' : ''}>{row[0]}</b><span>{row[1]}</span><code>{row[2]}</code></div>)}</GradientPanel></div> }
function TierScreen() { return <div className="account-screen"><div className="screen-title"><div><span className="eyebrow">ACCOUNT / TIER</span><h2>Pro desk status</h2></div><span className="tier-badge">PRO</span></div><GradientPanel className="tier-hero"><span className="eyebrow">CURRENT TIER</span><strong>PRO</strong><p>Performance fee <b>10%</b> <InfoTip>Applied only to gross profit above your high-water mark.</InfoTip></p><div className="tier-progress"><i /></div><small>$12,850 / $25,000 capital to Elite</small></GradientPanel><GradientPanel className="tier-table"><div className="table-row table-head"><span>TIER</span><span>CAPITAL</span><span>FEE</span></div>{[['Starter','$0','$25k','15%'],['Pro','$5k','$25k','10%'],['Elite','$25k+','—','7%']].map(r => <div className={`table-row ${r[0] === 'Pro' ? 'current' : ''}`} key={r[0]}><b>{r[0]}</b><span>{r[1]}–{r[2]}</span><strong>{r[3]}</strong></div>)}</GradientPanel><GradientPanel className="calculator"><span className="eyebrow">ILLUSTRATION · NOT A PROJECTION</span><h2>Capital + gross profit</h2><div className="calc-values"><div><small>CAPITAL</small><strong>$10,000</strong></div><div><small>GROSS PROFIT</small><strong>$1,000</strong></div><div><small>FEE AT PRO</small><strong>$100</strong></div></div><p>Fees apply above the high-water mark only. <InfoTip>HWM means the highest prior equity level used to prevent paying performance fees twice.</InfoTip></p></GradientPanel><GradientPanel className="stake-card"><span className="eyebrow">STAKE INFO</span><h2>Keep your tier active</h2><p>Stake requirements are informational and do not lock or move your funds.</p></GradientPanel></div> }
function AccountSection() {
  const [modal, setModal] = useState<'code' | 'notifications' | 'whitelist' | 'reset' | ''>('')
  const [saved, setSaved] = useState(false)
  const [codeDigits, setCodeDigits] = useState<string[]>(Array(6).fill(''))
  const [notifications, setNotifications] = useState<Record<string, boolean>>({
    'Trade fills': true,
    'Fees charged': true,
    Deposits: true,
    'Tank low': true,
    'HWM break': true,
  })
  const [reset, setReset] = useState(false)
  const [toast, setToast] = useState('')
  const [whitelistAddress, setWhitelistAddress] = useState('')
  const [whitelistChain, setWhitelistChain] = useState('')
  const [whitelistNickname, setWhitelistNickname] = useState('')
  const [savedWallets, setSavedWallets] = useState([{ chain: 'BNB Smart Chain', nickname: 'Jordan · BNB', address: '0x71F4...9aC28D' }])
  const [reviewWallet, setReviewWallet] = useState<{ chain: string; address: string; nickname: string } | null>(null)
  const notify = (message: string) => { setToast(message); window.setTimeout(() => setToast(''), 2400) }
  const chainPattern = whitelistChain.toLowerCase().includes('bnb') ? /^0x[a-fA-F0-9]{40}$/ : whitelistChain.toLowerCase().includes('sol') ? /^[1-9A-HJ-NP-Za-km-z]{32,44}$/ : /^0x[a-fA-F0-9]{40}$/
  return <div className="account-screen">
    <div className="screen-title"><div><span className="eyebrow">ACCOUNT / SECURITY</span><h2>Desk controls</h2></div><div className="security-chip">SECURE</div></div>
    {reset && <div className="account-feedback" role="status"><span className="status-chip running"><i />Desk reset applied</span><small>Active desk settings were cleared. Financial records remain intact.</small></div>}
    <GradientPanel className="profile-card"><div className="top-avatar">JD</div><div><strong>Jordan Davis</strong><small>Pro account · verified email</small></div><span className="status-chip running"><i />protected</span></GradientPanel>
    <div className="account-actions">
      <button className="account-action" onClick={() => setModal('code')}><span><ShieldCheck /></span><div><strong>Withdrawal security code</strong><small>{saved ? 'Active · tap to change' : 'Not set · protect approvals'}</small></div><ChevronRight /></button>
      <button className="account-action" onClick={() => setModal('notifications')}><span><Bell /></span><div><strong>Notifications</strong><small>{notifications ? '5 alerts enabled' : 'Notifications paused'}</small></div><ChevronRight /></button>
      <button className="account-action" onClick={() => setModal('whitelist')}><span><Wallet /></span><div><strong>Withdrawal whitelist</strong><small>{savedWallets.length} saved destination{savedWallets.length === 1 ? '' : 's'}</small></div><ChevronRight /></button>
      <button className="account-action danger-row" onClick={() => setModal('reset')}><span><Settings /></span><div><strong>Reset desk</strong><small>Retains all financial records</small></div><ChevronRight /></button>
    </div>
    {modal && <div className="modal-backdrop" onPointerDown={(event) => { if (event.target === event.currentTarget) setModal('') }}><GradientPanel className="confirm-modal account-modal" onPointerDown={event => event.stopPropagation()}>
      <button className="modal-close" aria-label="Close" onClick={() => setModal('')}><X /></button>
      {modal === 'code' && <><span className="eyebrow">SECURITY / WITHDRAWALS</span><h2>{saved ? 'Change security code' : 'Set security code'}</h2><p>{saved ? 'Enter a new 6-digit code to replace the current one.' : 'This code is required before approving withdrawals. Keep it private.'}</p><div className="code-boxes">{Array.from({length: 6}, (_, i) => <input key={i} type="password" inputMode="numeric" maxLength={1} value={codeDigits[i]} aria-label={`Security digit ${i + 1}`} onChange={event => { const digit = event.target.value.replace(/[^0-9]/g, '').slice(-1); setCodeDigits(previous => previous.map((value, index) => index === i ? digit : value)); if (digit) (event.currentTarget.nextElementSibling as HTMLInputElement | null)?.focus() }} onKeyDown={event => { if (event.key === 'Backspace' && !codeDigits[i] && i > 0) (event.currentTarget.previousElementSibling as HTMLInputElement | null)?.focus() }} />)}</div><button className="primary-action" disabled={codeDigits.some(digit => !digit)} onClick={() => { setSaved(true); setCodeDigits(Array(6).fill('')); setModal('') }}>Save code <ShieldCheck /></button></>}
      {modal === 'notifications' && <><span className="eyebrow">ACCOUNT / ALERTS</span><h2>Notification settings</h2><p>Choose which desk events reach you.</p>{['Trade fills','Fees charged','Deposits','Tank low','HWM break'].map(label => <label className="toggle-row" key={label}><span>{label}<small>Push and in-app alert</small></span><input type="checkbox" checked={notifications[label]} onChange={() => setNotifications(previous => ({ ...previous, [label]: !previous[label] }))} /><i /></label>)}<button className="primary-action" onClick={() => setModal('')}>Done <ChevronRight /></button></>}
      {modal === 'whitelist' && <><span className="eyebrow">WALLET / DESTINATIONS</span><h2>Withdrawal whitelist</h2><p>Saved addresses are shown here. A new address is never silently trusted.</p>{savedWallets.map(wallet => <div className="whitelist-item" key={`${wallet.chain}-${wallet.address}`}><span className="network-mark" /><div><strong>{wallet.nickname} · {wallet.chain}</strong><small className="mono">{wallet.address}</small></div><button className="ghost-action" onClick={() => { setSavedWallets(wallets => wallets.filter(item => item.address !== wallet.address)); notify('Whitelisted address removed') }}>Remove</button></div>)}<div className="whitelist-form"><input className="modal-input" placeholder="Chain · e.g. BNB Smart Chain" value={whitelistChain} onChange={event => setWhitelistChain(event.target.value)} /><input className="modal-input" placeholder="Wallet address" value={whitelistAddress} onChange={event => setWhitelistAddress(event.target.value.trim())} /><input className="modal-input" placeholder="Nickname" value={whitelistNickname} onChange={event => setWhitelistNickname(event.target.value)} /></div><small className="warning-copy">Always cross-check the full address and network. Address-poisoning scams use lookalike addresses.</small><button className="primary-action" disabled={!whitelistChain || !whitelistAddress || !chainPattern.test(whitelistAddress)} onClick={() => setReviewWallet({ chain: whitelistChain, address: whitelistAddress, nickname: whitelistNickname || 'New destination' })}>Review address <ChevronRight /></button></>}
      {modal === 'reset' && <><span className="eyebrow">DANGER / DESK RESET</span><h2>Reset this desk?</h2><p className="danger-copy">This clears active desk settings and bots. All financial records, ledger history, and withdrawal records are retained.</p><label className="confirm-check"><input type="checkbox" /> I understand this cannot be undone.</label><button className="danger-action" onClick={() => { setReset(true); setModal('') }}>Reset desk</button></>}
    </GradientPanel></div>}
    {reviewWallet && <div className="modal-backdrop" onPointerDown={event => { if (event.target === event.currentTarget) setReviewWallet(null) }}><GradientPanel className="confirm-modal account-modal" onPointerDown={event => event.stopPropagation()}><button className="modal-close" aria-label="Close address review" onClick={() => setReviewWallet(null)}><X /></button><span className="eyebrow">SECURITY / ADDRESS REVIEW</span><h2>Cross-check before saving</h2><p>Confirm every character against your wallet app. This protects against address-poisoning scams.</p><div className="facts-block mono">NETWORK · {reviewWallet.chain.toUpperCase()}<br />ADDRESS · {reviewWallet.address}<br />LABEL · {reviewWallet.nickname}</div><p className="warning-copy">TradePulse does not verify ownership of this address. You are responsible for the network and destination.</p><button className="primary-action" onClick={() => { setSavedWallets(wallets => [...wallets, { ...reviewWallet, address: reviewWallet.address.length > 16 ? `${reviewWallet.address.slice(0, 8)}...${reviewWallet.address.slice(-6)}` : reviewWallet.address }]); setWhitelistAddress(''); setWhitelistChain(''); setWhitelistNickname(''); setReviewWallet(null); setModal(''); notify('Address saved · 24-hour cooling period started') }}>I cross-checked · Save address <ShieldCheck /></button><button className="ghost-action" onClick={() => setReviewWallet(null)}>Edit address</button></GradientPanel></div>}
    {toast && <div className="desk-toast" role="status">{toast}</div>}
  </div>
}

function AccountScreen() { return <AccountSection /> }

function LegacyAccountScreen() { const [code, setCode] = useState(''); const [added, setAdded] = useState(false); return <div className="account-screen"><div className="screen-title"><div><span className="eyebrow">ACCOUNT / SECURITY</span><h2>Desk controls</h2></div><div className="security-chip">SECURE</div></div><GradientPanel className="profile-card"><div className="top-avatar">JD</div><div><strong>Jordan Davis</strong><small>Pro account · verified email</small></div><span className="status-chip running"><i />protected</span></GradientPanel><GradientPanel className="security-card"><div className="section-heading"><div><span className="eyebrow">SECURITY CODE</span><h2>{code.length === 6 ? 'Code saved' : 'Protect withdrawals'}</h2></div><ShieldCheck /></div>{code.length === 6 ? <div className="security-saved"><span className="status-chip running"><i />active</span><strong>Withdrawal code is set</strong><small>Your code is required before approving withdrawals. Keep it private.</small><button className="small-action" onClick={() => setCode('')}>Change code</button></div> : <><div className="code-boxes">{Array.from({length: 6}, (_, i) => <input key={i} id={`security-code-${i}`} type="password" inputMode="numeric" pattern="[0-9]*" autoComplete={i === 0 ? 'one-time-code' : 'off'} value={code[i] || ''} onChange={e => { const digits = e.target.value.replace(/\D/g, ''); if (!digits) return; setCode(current => { const next = current.split(''); digits.slice(0, 6 - i).split('').forEach((digit, offset) => { next[i + offset] = digit }); return next.join('').slice(0, 6) }); const nextIndex = Math.min(i + digits.length, 5); document.getElementById(`security-code-${nextIndex}`)?.focus() }} onPaste={e => { e.preventDefault(); const digits = e.clipboardData.getData('text').replace(/\D/g, '').slice(0, 6 - i); if (!digits) return; setCode(current => { const next = current.split(''); digits.split('').forEach((digit, offset) => { next[i + offset] = digit }); return next.join('').slice(0, 6) }); document.getElementById(`security-code-${Math.min(i + digits.length, 5)}`)?.focus() }} onKeyDown={e => { if (e.key === 'Backspace' && !code[i] && i > 0) document.getElementById(`security-code-${i - 1}`)?.focus() }} aria-label={`Security code digit ${i + 1}`} />)}</div><small>Six digits required before withdrawals can be approved.</small></>}</GradientPanel><GradientPanel className="whitelist-card"><div className="section-heading"><div><span className="eyebrow">WITHDRAWAL WHITELIST</span><h2>Saved destinations</h2></div><button className="small-action" onClick={() => setAdded(!added)}>{added ? 'Saved' : 'Add address'}</button></div>{added && <div className="whitelist-form"><input placeholder="Chain · Base" /><input placeholder="Wallet address" /><input placeholder="Nickname" /></div>}<div className="address-row"><span className="network-mark" /><div><strong>Base · Treasury</strong><code>0x71F4...9aC28D</code></div><span className="status-chip complete">approved</span></div><p>New addresses have a 24-hour cooling period. <InfoTip>Cooling protects your desk if a security code is compromised.</InfoTip></p></GradientPanel><GradientPanel className="notifications"><div className="section-heading"><div><span className="eyebrow">NOTIFICATIONS</span><h2>Keep me informed</h2></div><Bell /></div>{['Fills','Fees','Deposits','Tank low','HWM break'].map((label, i) => <label className="toggle-row" key={label}><span>{label}<small>Send a desk alert</small></span><input type="checkbox" defaultChecked={i < 3} /><i /></label>)}</GradientPanel><GradientPanel className="reset-card"><span className="eyebrow">RESET DESK</span><h2>Start fresh, keep the record.</h2><p>Resetting removes saved preferences and active sessions, but retains all financial records.</p><button className="danger-action">Reset desk <X /></button></GradientPanel></div> }

function Spark({ down = false }: { down?: boolean }) { return <svg className={`desk-spark ${down ? 'down' : ''}`} viewBox="0 0 110 30" preserveAspectRatio="none" aria-label="Price sparkline"><path d={down ? 'M2 6 C18 4 20 16 34 12 S53 9 66 18 S89 16 108 26' : 'M2 24 C16 25 20 13 34 18 S51 4 66 12 S88 7 108 2'} fill="none" stroke="currentColor" strokeWidth="2" /></svg> }
function LiveDesk() { const [alert, setAlert] = useState(false); const prices = [['BTC/USD','$67,842.10','+2.41%',false],['ETH/USD','$3,842.66','+1.08%',false],['SOL/USD','$182.44','-0.74%',true],['PEPE/USD','$0.0000124','+8.92%',false]]; return <div className="desk-screen"><div className="screen-title"><div><span className="eyebrow">LIVE DESK / MARKET DATA</span><h2>Price board</h2></div><span className="live-indicator"><i />LIVE</span></div><GradientPanel className="price-board">{prices.map(([name,price,change,down]) => <div className="asset-row" key={name}><span className="asset-ident">{name[0]}</span><div><strong>{name}</strong><small>Spot market</small></div><strong className="asset-price">{price}</strong><span className={`activity-status ${down ? 'review' : 'complete'}`}>{change}</span><Spark down={down as boolean} /></div>)}</GradientPanel><div className="desk-columns"><GradientPanel className="pulse-feed"><div className="section-heading"><div><span className="eyebrow">MARKET PULSE</span><h2>What is moving</h2></div><span className="mono">LIVE</span></div>{['PEPE breaks 24h high resistance','BTC volume is accelerating','SOL pullback meets support'].map((item,i)=><div className="audit-row" key={item}><span className="status-dot" /><div><strong>{item}</strong><small>{i+2}m ago · automated signal</small></div></div>)}</GradientPanel><GradientPanel className="alert-card"><span className="eyebrow">ALERT COMPOSER</span><h2>Get the signal first.</h2><div className="alert-fields"><select aria-label="Alert asset" defaultValue="BTC/USD"><option>BTC/USD</option><option>ETH/USD</option><option>PEPE/USD</option></select><select aria-label="Alert condition" defaultValue="above"><option>above</option><option>below</option></select><input aria-label="Alert price" defaultValue="70000" /></div><div className="parsed-preview"><span>PARSED PREVIEW</span><code>BTC/USD above $70,000</code></div><button className="primary-action" onClick={() => setAlert(true)}>Create alert <Bell /></button>{alert && <div className="toast-inline"><span className="status-dot" />Alert active · monitoring BTC/USD</div>}</GradientPanel></div><GradientPanel className="active-alerts"><div className="section-heading"><div><span className="eyebrow">ACTIVE ALERTS</span><h2>Watching 2 conditions</h2></div><button className="small-action">Clear all</button></div>{[['BTC/USD above $70,000','Created today'],['PEPE/USD below $0.000010','Created yesterday']].map(item=><div className="audit-row" key={item[0]}><span className="alert-pip" /><div><strong>{item[0]}</strong><small>{item[1]}</small></div><button className="icon-button" aria-label="Remove alert"><X /></button></div>)}</GradientPanel><GradientPanel className="announcements"><span className="eyebrow">ANNOUNCEMENTS</span><h2>Desk notices</h2><div className="audit-row"><span className="status-dot" /><div><strong>Base network maintenance window</strong><small>Withdrawals may take longer · 18 Sep 2026</small></div></div></GradientPanel></div> }
